// Exact branch-and-bound: rows must be independent in lower, every seven still blue in upper remains a demand. Repeats allowed by bounds(). No anchor assumptions.
#[path="ramsey_38_six_screen.rs"] mod screen;use std::io::{self,BufRead};fn tree(a:&mut Vec<u32>,ed:&[(usize,usize)],nodes:&mut u64,prunes:&mut u64,leaves:&mut u64){*nodes+=1;let mut b=a.clone();let es:Vec<_>=ed.iter().copied().filter(|&(i,j)|a[i]&a[j]==0).collect();for &(i,j) in &es{b[i]|=1<<j;b[j]|=1<<i}if !screen::bounds(a,&b,7,7){*prunes+=1;return}if es.is_empty(){*leaves+=1;println!("{}",a.iter().map(|v|v.to_string()).collect::<Vec<_>>().join(" "));return}let(i,j)=es[0];tree(a,&es[1..],nodes,prunes,leaves);a[i]|=1<<j;a[j]|=1<<i;tree(a,&es[1..],nodes,prunes,leaves);a[i]^=1<<j;a[j]^=1<<i}fn main(){for l in io::stdin().lock().lines(){let mut a:Vec<u32>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let mut e=vec![];for i in 0..a.len(){for j in 0..i{if a[i]>>j&1==0 && a[i]&a[j]==0{e.push((i,j))}}}let(mut n,mut p,mut k)=(0,0,0);tree(&mut a,&e,&mut n,&mut p,&mut k);eprintln!("nodes {n} prunes {p} passing_leaves {k}")}}
